arguments.query:
metric this_week_run_km = run_distance_km | where(activities.week_start == max(activities.week_start));
metric avg_4wk_run_km = unique(activities.week_start) | select(v: run_distance_km) | avg(v);
explore {
  measures {
    this_week_km: this_week_run_km,
    avg_4wk_km: avg_4wk_run_km
  }
}
